import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import crypto from 'node:crypto';
const tab=await(await fetch('http://127.0.0.1:9222/json/new?about:blank',{method:'PUT'})).json();const ws=new WebSocket(tab.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});let id=0;const pending=new Map(),errors=[],failed=[];
ws.onmessage=({data})=>{const m=JSON.parse(data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.method==='Network.responseReceived'&&m.params.response.status>=400&&!m.params.response.url.endsWith('favicon.ico'))failed.push(m.params.response.url);if(pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);}};
/** Executa um comando no Chrome com prazo limitado. */
function send(method,params={}){return new Promise((resolve,reject)=>{const serial=++id,timer=setTimeout(()=>reject(Error('Tempo excedido: '+method)),25000);pending.set(serial,{resolve:r=>{clearTimeout(timer);resolve(r);},reject:e=>{clearTimeout(timer);reject(e);}});ws.send(JSON.stringify({id:serial,method,params}));});}
/** Consulta o jogo sem ocultar erros da avaliação. */
async function evaluate(expression){const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;}
/** Aguarda uma condição sem bloquear a página. */
async function until(expression){for(let i=0;i<200;i++){if(await evaluate(expression))return;await new Promise(r=>setTimeout(r,100));}throw Error('Condição não alcançada: '+expression);}
/** Clica no centro real do botão, para verificar alinhamento e eventos de ponteiro. */
async function click(selector){const p=await evaluate(`(()=>{const r=document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2};})()`);await send('Input.dispatchMouseEvent',{type:'mousePressed',...p,button:'left',clickCount:1});await send('Input.dispatchMouseEvent',{type:'mouseReleased',...p,button:'left',clickCount:1});}
/** Registra a captura temporária com tamanho e hash, sem versionar o bitmap. */
async function capture(name){const raw=await send('Page.captureScreenshot',{format:'png'}),bytes=Buffer.from(raw.data,'base64'),file='/tmp/tela-inicial-'+name+'.png';await fs.writeFile(file,bytes);return{file,bytes:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex')};}
const difficulty=process.argv[2]||'NORMAL';assert.ok(['NORMAL','EASY'].includes(difficulty));const resume=process.argv.includes('--resume');
const wait=ms=>new Promise(r=>setTimeout(r,ms));const held=new Set(),events=[],captures=[];
const keyValue={Space:' ',KeyE:'e',KeyP:'p',KeyM:'m'};
const virtual={Space:32,ArrowLeft:37,ArrowRight:39,ArrowUp:38,ArrowDown:40,KeyE:69,KeyP:80,KeyM:77};
/** Envia somente teclado nativo; não escreve controles internos nem avança a simulação. */
async function key(code,type){await send('Input.dispatchKeyEvent',{type,code,key:keyValue[code]||code,windowsVirtualKeyCode:virtual[code]});}
async function tap(code){await key(code,'keyDown');await key(code,'keyUp');}
async function keys(next){const wanted=new Set(next);for(const k of held)if(!wanted.has(k)){await key(k,'keyUp');held.delete(k)}for(const k of wanted)if(!held.has(k)){await key(k,'keyDown');held.add(k)}}
async function record(event,details={}){const e={event,seconds:+((Date.now()-start)/1000).toFixed(2),difficulty,...details};events.push(e);console.log(JSON.stringify(e));await fs.writeFile('/tmp/legendgirl-real-status.json',JSON.stringify(e));}
async function shot(name){const x=await capture('real-'+difficulty+'-'+name);captures.push(x);console.log('CAPTURA',JSON.stringify(x));}
const inspect=`(()=>{const s=game.state,b=s.baby,r=s.toyRoomInstance?.instance,a=r?.battle,bs=a?.state,e=bs?.enemy,c=r?.chase;return {difficulty:s.gameDifficulty,mode:s.currentPhaseMode,play:s.gameplayState,over:s.isGameOver,phase3:s.isPhase3,level:s.phase3Level,escape:s.isEscapeMode,escapeLevel:s.escapeLevel,standby:s.isStandbyActive,transition:s.isStandbyTransitioning,cutscene:s.cutsceneActive,cutsceneStep:s.cutsceneStep,plot:s.plotTwistActive,plotStep:s.plotTwistStep,tutorial:s.phase3TutorialActive,portal:s.truePortalTransitionActive,intro:game.toyRoomIntroduction.active,ground:game.isGrounded(),narrative:game.isCutsceneActive(),baby:{x:b.x,y:b.y,w:b.w,h:b.h,vy:b.vy,vx:b.vx,jumpPower:b.jumpPower,gravity:b.gravity,index:b.currentPlatformIndex,onGround:b.onGround},room:r?{player:{x:r.player.x,y:r.player.y,radius:r.player.radius,speed:r.player.speed,carried:r.player.carriedItem?.id},toys:r.toys.map(t=>({id:t.id,x:t.x,y:t.y,organized:t.isOrganized,carried:t.isCarried,returned:t.returnGeneration})),furniture:r.furniture.map(f=>({id:f.id,x:f.x,y:f.y,w:f.w,h:f.h})),organized:r.organizedCount,tutorial:r.tutorial.active,story:structuredClone(r.story.state),arena:r.arena.state.status,difficulty:r.gameDifficulty}:null,battle:bs?{mode:bs.mode,transition:Boolean(bs.transition),x:r.player.x,enemyX:e.x,actor:e.actor,enemyHp:e.hp,hp:bs.player.hp,enemyState:e.state,attack:e.attack,enemyElapsed:e.elapsed,jump:bs.jump,cooldown:bs.cooldown,attackTime:bs.attackTime,guard:a.enemyGuarding(),range:a.getSwordRange(e.actor),contact:a.getEnemyCollisionDistance(e.actor),history:bs.history.filter(x=>['PLAYER_HIT','ENEMY_HIT','SWORD_BLOCKED','DEFEATED'].includes(x.event)),reaction:bs.playerHitTime}:null,chase:c?{stage:c.state.stage,distance:c.state.distance,x:c.state.x,gap:c.state.gap,hits:c.state.hits,chest:c.state.chestApplied,ready:c.ready,error:c.error,obstacles:c.state.obstacles.map(o=>({x:o.x,z:o.z})),campaign:c.campaign}:null};})()`;
let start=Date.now(),lastAction=0,lastStatus=0,lastStage='',deaths=0,path=[],targetId='',lastPlan=0,lastAttack=0,finished=false,checkedReload=false,testedArenaDefeat=false;
/** Planeja caminhada sobre coordenadas livres; a execução usa as setas reais em tempo normal. */
function plan(room,target,radius){
 const free=(x,y)=>{if(x<99||x>1501||y<274||y>1101)return false;return !room.furniture.some(f=>x>f.x-room.player.radius&&x<f.x+f.w+room.player.radius&&y>f.y-room.player.radius&&y<f.y+f.h+room.player.radius)};
 const begin=[Math.round(room.player.x/20),Math.round(room.player.y/20)],name=p=>p.join(',');
 const q=[begin],seen=new Map([[name(begin),null]]);let end;
 for(let i=0;i<q.length;i++){const p=q[i];if(Math.hypot(p[0]*20-target.x,p[1]*20-target.y)<radius){end=p;break}for(const[dX,dY]of[[1,0],[-1,0],[0,1],[0,-1]]){const n=[p[0]+dX,p[1]+dY];if(seen.has(name(n))||!free(n[0]*20,n[1]*20))continue;seen.set(name(n),p);q.push(n)}}
 if(!end)throw Error('Sem caminho até '+JSON.stringify(target));const route=[];for(let p=end;p;p=seen.get(name(p)))route.unshift({x:p[0]*20,y:p[1]*20});return route;
}
try{
 await send('Runtime.enable');await send('Page.enable');await send('Network.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1200,height:720,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:'http://127.0.0.1:3000/'});await until('Boolean(window.game)');
 // O perfil é exclusivo de QA. Limpar a campanha só prepara uma partida nova no navegador isolado.
 if(!resume)await evaluate('localStorage.clear()');await send('Page.reload');await until('Boolean(window.game)');await evaluate('game.assetsReady');
 await shot('menu');await click('#btn-title-options');assert.equal(await evaluate('document.querySelector("#title-options-dialog").open'),true);await shot('opcoes');await click('#btn-close-title-options');
 if(difficulty==='EASY')await click('#btn-easy-mode');await click(resume?'#btn-load-game':'#btn-start-phase1');
 await record('inicio-pela-interface',{selected:await evaluate('game.state.gameDifficulty')});
 const cfg=await evaluate(`(async()=>{const m=await import('/src/js/config.js');return {platforms:m.platforms,phase3:m.phase3Platforms,approach:Array.from({length:10},(_,i)=>m.getApproachJumpSpeed(i-1)),escape:Array.from({length:12},(_,i)=>m.getEscapeStats(i)),phase3stats:Array.from({length:15},(_,i)=>m.getPhase3Stats(i)),floor:m.getPhase3Stats(0,true)}})()`);
 while(Date.now()-start<1500000){
  const s=await evaluate(inspect),now=Date.now();
  const stage=s.chase?'fuga:'+s.chase.stage:s.battle?'arena:'+s.battle.mode+':'+s.battle.actor:s.mode==='toy-room'?'sala:'+s.room.story.investigationStage:s.play+':'+s.phase3+':'+s.baby.index+':'+s.cutscene+':'+s.plot;
  if(stage!==lastStage){await record('etapa',{stage,hp:s.battle?.hp,hits:s.chase?.hits,organized:s.room?.organized,returned:s.room?.story.returnedToyCount});lastStage=stage;if(s.chase&&['BEAR_DOWN','RUNNING','COMPLETE','GAME_OVER'].includes(s.chase.stage)||s.room&&['INVESTIGATION','SEEKING_SWORD'].includes(s.room.story.investigationStage)&&!events.some(e=>e.captureStage===stage)){await shot(stage.replaceAll(':','-'));events.push({captureStage:stage})}}
  if(now-lastStatus>5000){await fs.writeFile('/tmp/legendgirl-real-status.json',JSON.stringify({difficulty,seconds:Math.round((now-start)/1000),stage,deaths,s}));lastStatus=now}
  if(s.over){await keys([]);await shot('derrota-'+deaths);await record('derrota',{index:s.baby.index,phase3:s.phase3});if(++deaths>6)throw Error('Mais de seis derrotas; interrompida a campanha real');await click('#btn-retry');await wait(500);continue}
  if(s.mode!=='toy-room'){
   await keys([]);
   if(difficulty==='EASY'&&!checkedReload&&s.escape&&!s.cutscene&&s.baby.index===9&&s.baby.onGround){
    await tap('KeyP');const before=await evaluate('JSON.stringify(game.state.baby)');await wait(350);assert.equal(await evaluate('JSON.stringify(game.state.baby)'),before,'Pausa deve congelar a menina');await shot('pausa-castelo');
    await send('Page.reload');await until('Boolean(window.game)');await click('#btn-load-game');assert.equal(await evaluate('game.state.gameDifficulty'),'EASY');checkedReload=true;await record('pausa-e-recarga-real',{restored:await evaluate('game.state.baby.currentPlatformIndex')});continue;
   }
   if(s.ground||s.narrative||s.play==='FIRST_JUMP_TUTORIAL'){
    let jump=false;
    if(s.play==='FIRST_JUMP_TUTORIAL'||s.standby||s.cutscene||(s.plot&&s.plotStep>=4))jump=now-lastAction>500;
    else if(s.ground&&!s.plot&&!s.tutorial&&!s.portal&&!s.transition){
     const list=s.phase3?cfg.phase3:cfg.platforms,next=list[s.baby.index+1];
     if(next){const p=next.standRegion||next,Y=next.surfaceTopY??p.y??next.y;
      let v=s.baby.jumpPower,vx=cfg.approach[Math.min(9,s.baby.index+1)];
      if(s.phase3){const stats=s.baby.index<0?cfg.floor:cfg.phase3stats[s.level];v=stats.jumpPower;vx=stats.airVx}else if(s.escape){const stats=cfg.escape[s.escapeLevel];v=stats.jumpPower;vx=stats.airVx}
      const t=(-v+Math.sqrt(Math.max(0,v*v+2*s.baby.gravity*(Y-s.baby.y-s.baby.h))))/s.baby.gravity;
      const from=list[s.baby.index],support=from?(from.standRegion||from):null;
      const minSupport=support?support.x-s.baby.w+4:-Infinity,maxSupport=support?support.x+support.w-4:Infinity;
      const minLaunch=Math.max(minSupport,p.x-s.baby.w-vx*t+4),maxLaunch=Math.min(maxSupport,p.x+p.w-vx*t-4);
      const launch=(minLaunch+maxLaunch)/2;
      jump=s.escape&&s.baby.index===9||vx>0?s.baby.x>=launch:s.baby.x<=launch;
      if(s.escape&&s.baby.index===9)jump=true;
      if(jump&&now-lastAction>220){await record('salto',{phase3:s.phase3,index:s.baby.index,x:+s.baby.x.toFixed(2),launch:+launch.toFixed(2),t:+t.toFixed(2)})}
     }
    }
    if(jump&&now-lastAction>220){await tap('Space');lastAction=now}
   }
  }else if(s.chase){
   const c=s.chase;await keys([]);
   if(c.error)throw Error(c.error);
   if(c.stage==='RUNNING'){
    const next=c.obstacles.filter(o=>o.z>=c.distance-.1).sort((a,b)=>a.z-b.z)[0];
    if(next){const group=c.obstacles.filter(o=>Math.abs(o.z-next.z)<.01),choices=[-2.4,0,2.4].filter(x=>group.every(o=>Math.abs(o.x-x)>1)).sort((a,b)=>Math.abs(a-c.x)-Math.abs(b-c.x));const dx=choices[0]-c.x;await keys(Math.abs(dx)<.13?[]:[dx>0?'ArrowRight':'ArrowLeft'])}
   }
   if(c.stage==='GAME_OVER'){await record('derrota-fuga',c);throw Error('Derrota durante fuga real')}
   if(c.stage==='COMPLETE'){await record('campanha-concluida',{deaths,chase:c});finished=true;break}
  }else if(s.battle&&s.room.arena==='COMBAT'){
   const b=s.battle;if(b.mode==='DEFEAT'){await keys([]);if(!testedArenaDefeat){await shot('derrota-arena');await record('derrota-arena-intencional',{hp:b.hp,actor:b.actor});testedArenaDefeat=true}if(now-lastAction>1200){await tap('Space');lastAction=now}continue}
   if(b.mode!=='BATTLE'||b.transition){await keys([]);await wait(60);continue}
   // Exercita a tela de derrota e a nova tentativa sem retirar vida por instrumentação.
   if(difficulty==='EASY'&&!testedArenaDefeat){await keys([b.enemyX>=b.x?'ArrowRight':'ArrowLeft']);await wait(25);continue}
   const toward=b.enemyX>=b.x?'ArrowRight':'ArrowLeft',distance=Math.abs(b.enemyX-b.x),next=[];let strike=false;
   if(distance>Math.min(b.range-12,b.contact+25))next.push(toward);
   if(b.enemyState==='ATTACK'){
    const end=b.attack==='Toy Leap'?96:72,crouch=['Laser Beam','Rocket Punch'].includes(b.attack);if(crouch&&b.enemyElapsed<end)next.push('ArrowDown');
    const jumpAt=b.attack==='Toy Leap'?48:24;if(!crouch&&b.enemyElapsed>=jumpAt&&b.enemyElapsed<jumpAt+14&&b.jump===0)next.push('ArrowUp');
    strike=b.enemyElapsed>=end&&!b.guard&&b.jump<85&&distance<b.range&&b.cooldown===0;
   }else strike=!['HIT','ENRAGE'].includes(b.enemyState)&&b.jump<85&&distance<b.range-5&&b.cooldown===0;
   await keys(next);if(strike&&now-lastAttack>150){await tap('Space');lastAttack=now}
  }else if(s.room){
   const r=s.room,st=r.story;
   if(['INVESTIGATION','PICKUP','EQUIPPED'].includes(st.investigationStage)||['TRANSFORMING','RETURNING'].includes(r.arena)){await keys([]);await wait(60);continue}
   let target,range,id;
   if(st.investigationStage==='SEEKING_SWORD'){target=st.sword;range=30;id='sword'}
   else if(r.player.carried){const chest=r.furniture.find(f=>f.id==='toy-chest');target={x:chest.x+chest.w/2,y:chest.y+chest.h/2};range=135;id='chest'}
   else{const toy=r.toys.filter(t=>!t.organized&&!t.carried).sort((a,b)=>Math.hypot(a.x-r.player.x,a.y-r.player.y)-Math.hypot(b.x-r.player.x,b.y-r.player.y))[0];if(toy){target=toy;range=65;id=toy.id}}
   if(!target){await keys([]);await wait(60);continue}
   const d=Math.hypot(target.x-r.player.x,target.y-r.player.y);
   if(d<range){await keys([]);if(now-lastAction>420){await tap('KeyE');lastAction=now;await record('acao-sala',{target:id,distance:+d.toFixed(1)})}}
   else{
    if(id!==targetId||now-lastPlan>1800||!path.length){path=plan(r,target,range-8);targetId=id;lastPlan=now}
    while(path.length&&Math.hypot(path[0].x-r.player.x,path[0].y-r.player.y)<8)path.shift();
    if(path.length){const dx=path[0].x-r.player.x,dy=path[0].y-r.player.y;await keys([...(Math.abs(dx)>5?[dx>0?'ArrowRight':'ArrowLeft']:[]),...(Math.abs(dy)>5?[dy>0?'ArrowDown':'ArrowUp']:[])])}
   }
  }
  await wait(25);
 }
 assert.ok(finished,'A campanha precisa terminar pela interface.');
 await keys([]);
 // Completar a campanha e depois usar a prévia pelo seletor preserva o progresso real.
 if(difficulty==='EASY'){
  await wait(1100);
  await click('#btn-debug-phase-toggle');await send('Runtime.evaluate',{expression:`document.querySelector('#debug-phase-select').focus()`});
  await key('ArrowDown','keyDown');await key('ArrowDown','keyUp');
  // O select nativo recebe a opção pelo teclado, incluindo a confirmação por Enter.
  await send('Input.dispatchKeyEvent',{type:'keyDown',key:'End',code:'End',windowsVirtualKeyCode:35});await send('Input.dispatchKeyEvent',{type:'keyUp',key:'End',code:'End',windowsVirtualKeyCode:35});
  await send('Input.dispatchKeyEvent',{type:'keyDown',key:'Enter',code:'Enter',windowsVirtualKeyCode:13});await send('Input.dispatchKeyEvent',{type:'keyUp',key:'Enter',code:'Enter',windowsVirtualKeyCode:13});
  await until('Boolean(game.state.toyRoomInstance?.instance.chase?.ready)');
  const lossStart=Date.now();let loss;
  while(Date.now()-lossStart<180000){
   const s=await evaluate(inspect),c=s.chase;if(!c)throw Error('Prévia não iniciou');
   if(c.stage==='GAME_OVER'){await keys([]);await shot('derrota-fuga');await record('derrota-fuga-intencional',{hits:c.hits,campaign:c.campaign,chest:c.chest});loss=c;break}
   if(c.stage==='RUNNING'){const o=c.obstacles.filter(o=>o.z>=c.distance-.1).sort((a,b)=>a.z-b.z)[0];const dx=o?o.x-c.x:0;await keys(Math.abs(dx)>.1?[dx>0?'ArrowRight':'ArrowLeft']:[])}else await keys([]);
   await wait(25);
  }
  assert.ok(loss&&!loss.chest&&loss.hits===6,'Derrota real da prévia EASY precisa ocorrer no sexto impacto, sem baú');
 }
 assert.deepEqual(errors,[]);assert.deepEqual(failed,[]);
 console.log('APROVADO: campanha em tempo real por mouse/teclado nativos, sem escrita no estado, sem avanço manual, sem procura de saltos por rollback.',JSON.stringify({difficulty,events,captures,seconds:(Date.now()-start)/1000}));
}finally{await keys([]);ws.close();await fetch('http://127.0.0.1:9222/json/close/'+tab.id);}
